      @Membership.mem.{u_1, u_1} ι (Set.{u_1} ι) (@Set.instMembership.{u_1} ι) s i →
        @Membership.mem.{u_2, u_2} (α i) (Set.{u_2} (α i)) (@Set.instMembership.{u_2} (α i)) (t i) (f i))

